const items = $input.all().map(item => item.json);

function clean(value) {
  if (value === null || value === undefined || value === '') {
    return null;
  }

  return String(value).trim();
}

function firstSentence(text) {
  if (!text) return null;

  const cleaned = String(text).replace(/\s+/g, ' ').trim();

  const match = cleaned.match(/^.*?[.!?](?:\s|$)/);

  if (match) {
    return match[0].trim();
  }

  return cleaned.length > 220
    ? cleaned.slice(0, 217) + '...'
    : cleaned;
}

function formatOpportunity(item, index) {
  const decisionEmoji =
    item.decision === 'APPLY'
      ? '🟢'
      : item.decision === 'REVIEW'
      ? '🟡'
      : '⚪';

  const source = clean(item.source);
  const budget = clean(item.budget_text);
  const location = clean(item.location);
  const workMode = clean(item.work_mode);

  const meta = [
    source,
    budget,
    location,
    workMode && workMode !== 'unknown' ? workMode : null
  ]
    .filter(Boolean)
    .join(' • ');

  const summary = firstSentence(item.summary);

  return [
    `${decisionEmoji} ${index}. ${item.title}`,
    `${item.decision} • ${item.total_score}/18`,
    meta || null,
    summary || null,
    item.url
  ]
    .filter(Boolean)
    .join('\n');
}

const applyItems = items.filter(item => item.decision === 'APPLY');
const reviewItems = items.filter(item => item.decision === 'REVIEW');

const sections = [];

if (applyItems.length > 0) {
  const formatted = applyItems.map((item, index) =>
    formatOpportunity(item, index + 1)
  );

  sections.push(
    `🚀 APPLY — ${applyItems.length}\n\n${formatted.join('\n\n')}`
  );
}

if (reviewItems.length > 0) {
  const formatted = reviewItems.map((item, index) =>
    formatOpportunity(item, applyItems.length + index + 1)
  );

  sections.push(
    `👀 REVIEW — ${reviewItems.length}\n\n${formatted.join('\n\n')}`
  );
}

const header =
  `📌 AI / Automation Opportunities\n` +
  `Найдено: ${items.length} • APPLY: ${applyItems.length} • REVIEW: ${reviewItems.length}`;

const fullMessage =
  `${header}\n\n${sections.join('\n\n──────────\n\n')}`;

// Telegram limit is 4096 characters.
// Keep some safety margin.
const MAX_LENGTH = 3800;

const messages = [];

if (fullMessage.length <= MAX_LENGTH) {
  messages.push(fullMessage);
} else {
  let current = header;

  const blocks = [];

  if (applyItems.length > 0) {
    blocks.push(`🚀 APPLY — ${applyItems.length}`);

    applyItems.forEach((item, index) => {
      blocks.push(formatOpportunity(item, index + 1));
    });
  }

  if (reviewItems.length > 0) {
    blocks.push(`👀 REVIEW — ${reviewItems.length}`);

    reviewItems.forEach((item, index) => {
      blocks.push(
        formatOpportunity(
          item,
          applyItems.length + index + 1
        )
      );
    });
  }

  for (const block of blocks) {
    const candidate = `${current}\n\n${block}`;

    if (candidate.length > MAX_LENGTH) {
      messages.push(current);
      current = block;
    } else {
      current = candidate;
    }
  }

  if (current) {
    messages.push(current);
  }
}

return messages.map((message, index) => ({
  json: {
    message,
    message_part: index + 1,
    message_parts_total: messages.length,

    delivered_evaluations:
      index === messages.length - 1
        ? items.map(item => ({
            evaluation_id: item.evaluation_id,
            opportunity_id: item.opportunity_id,
            decision: item.decision,
            total_score: item.total_score
          }))
        : []
  }
}));

const digestItems = $('Build Telegram Digest').all();

const delivered = digestItems.flatMap(
  item => item.json.delivered_evaluations ?? []
);

return delivered.map(item => ({
  json: {
    evaluation_id: item.evaluation_id,
    opportunity_id: item.opportunity_id,
    decision: item.decision,
    total_score: item.total_score
  }
}));
